import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.NkeMC67b.js";const p=JSON.parse(`{"title":"Privacy & usage tracking","description":"Exactly what data Sikshya's optional usage tracking collects, what it never collects, where it's sent, how often, and how to enable / disable it. Privacy-safe and minimal.","frontmatter":{"title":"Privacy & usage tracking","description":"Exactly what data Sikshya's optional usage tracking collects, what it never collects, where it's sent, how often, and how to enable / disable it. Privacy-safe and minimal."},"headers":[],"relativePath":"privacy-tracking.md","filePath":"privacy-tracking.md","lastUpdated":1778327862000}`),n={name:"privacy-tracking.md"};function s(r,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-usage-tracking" tabindex="-1">Privacy &amp; usage tracking <a class="header-anchor" href="#privacy-usage-tracking" aria-label="Permalink to &quot;Privacy &amp; usage tracking&quot;">​</a></h1><p>Sikshya includes an optional <strong>usage tracking</strong> feature so we (MantraBrain) can understand how the plugin is used in real-world environments and prioritise improvements.</p><blockquote><p>Usage tracking is <strong>opt-in</strong> and <strong>disabled by default</strong> unless you say &quot;Yes&quot; during the setup wizard. You can flip it on or off any time.</p></blockquote><h2 id="you-are-in-control" tabindex="-1">You are in control <a class="header-anchor" href="#you-are-in-control" aria-label="Permalink to &quot;You are in control&quot;">​</a></h2><p>Usage tracking can be enabled or disabled any time from:</p><div class="screen-path">Sikshya → Settings → Advanced → Privacy &amp; Usage → &quot;Share anonymous usage data&quot;</div><p>The first-time <strong>setup wizard</strong> also asks for explicit consent. Choosing &quot;No&quot; means nothing is sent — ever.</p><h2 id="where-the-data-is-sent" tabindex="-1">Where the data is sent <a class="header-anchor" href="#where-the-data-is-sent" aria-label="Permalink to &quot;Where the data is sent&quot;">​</a></h2><p>When enabled, Sikshya sends a small JSON payload to MantraBrain&#39;s collection endpoint:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://usage.mantrabrain.com/index.php?rest_route=/mantrabrain/v1/collect</span></span></code></pre></div><p>The payload is signed with your site&#39;s instance ID (a random UUID generated locally — not your name, not your email).</p><h2 id="how-often-the-data-is-sent" tabindex="-1">How often the data is sent <a class="header-anchor" href="#how-often-the-data-is-sent" aria-label="Permalink to &quot;How often the data is sent&quot;">​</a></h2><p>When enabled, Sikshya may send usage data:</p><ul><li><strong>Once weekly</strong> via a scheduled background sync (<code>wp-cron</code>).</li><li><strong>Shortly after enabling tracking</strong> — an immediate first sync so we know it&#39;s wired up.</li><li><strong>Fallback inside wp-admin</strong> if the scheduled cron event didn&#39;t run, so the weekly cadence isn&#39;t missed on low-traffic sites.</li></ul><p>If a send fails (network blip, MantraBrain endpoint slow), Sikshya retries later with a backoff delay.</p><h2 id="what-data-is-collected" tabindex="-1">What data IS collected <a class="header-anchor" href="#what-data-is-collected" aria-label="Permalink to &quot;What data IS collected&quot;">​</a></h2><p>Below is the <strong>exact</strong> payload structure. Nothing more is sent.</p><h3 id="_1-product-instance-identifiers" tabindex="-1">1. Product + instance identifiers <a class="header-anchor" href="#_1-product-instance-identifiers" aria-label="Permalink to &quot;1. Product + instance identifiers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td><code>product</code></td><td><code>sikshya</code></td></tr><tr><td><code>instance_id</code></td><td>A random UUID like <code>8c1b9d62-...</code> — saved on your site so we can distinguish one site from another <strong>without identifying a person</strong></td></tr><tr><td><code>sent_at</code></td><td>UTC timestamp when the payload was sent</td></tr></tbody></table><h3 id="_2-site-information" tabindex="-1">2. Site information <a class="header-anchor" href="#_2-site-information" aria-label="Permalink to &quot;2. Site information&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td><code>site_url</code></td><td>Your site&#39;s home URL (e.g. <code>https://example.com</code>)</td></tr><tr><td><code>locale</code></td><td>Site language / locale (e.g. <code>en_US</code>, <code>de_DE</code>)</td></tr></tbody></table><h3 id="_3-environment-information" tabindex="-1">3. Environment information <a class="header-anchor" href="#_3-environment-information" aria-label="Permalink to &quot;3. Environment information&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td><code>wp_version</code></td><td>WordPress version (e.g. <code>6.5.2</code>)</td></tr><tr><td><code>php_version</code></td><td>PHP version (e.g. <code>8.2.10</code>)</td></tr><tr><td><code>multisite</code></td><td><code>true</code> or <code>false</code></td></tr></tbody></table><h3 id="_4-plugin-information" tabindex="-1">4. Plugin information <a class="header-anchor" href="#_4-plugin-information" aria-label="Permalink to &quot;4. Plugin information&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td><code>plugin_version</code></td><td>Sikshya plugin version (e.g. <code>1.4.2</code>)</td></tr></tbody></table><h3 id="_5-coarse-usage-signals-counts-status" tabindex="-1">5. Coarse usage signals (counts / status) <a class="header-anchor" href="#_5-coarse-usage-signals-counts-status" aria-label="Permalink to &quot;5. Coarse usage signals (counts / status)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Example</th></tr></thead><tbody><tr><td><code>published_courses_count</code></td><td>Integer count of published courses</td></tr><tr><td><code>published_lessons_count</code></td><td>Integer count of published lessons</td></tr><tr><td><code>setup_completed</code></td><td><code>true</code> if the setup wizard was completed</td></tr></tbody></table><p>That&#39;s it. No emails, no names, no order data, no learner data.</p><h2 id="what-is-not-tracked" tabindex="-1">What is NOT tracked <a class="header-anchor" href="#what-is-not-tracked" aria-label="Permalink to &quot;What is NOT tracked&quot;">​</a></h2><p>Sikshya usage tracking is intentionally minimal. The payload <strong>never</strong> contains:</p><ul><li>Student / learner names</li><li>Student / learner email addresses</li><li>Customer billing / shipping details</li><li>Order or payment data, transaction IDs</li><li>Course content or lesson content</li><li>Quiz answers, assignment submissions, gradebook entries</li><li>Individual user activity / per-user progress</li><li>IP addresses</li><li>Browser user-agent strings</li><li>Any WordPress admin username or password</li></ul><h2 id="privacy-commitments" tabindex="-1">Privacy commitments <a class="header-anchor" href="#privacy-commitments" aria-label="Permalink to &quot;Privacy commitments&quot;">​</a></h2><ul><li>The data is anonymous and aggregated.</li><li>Disabling usage tracking immediately stops future sends.</li><li>Existing data already collected is aggregated and not tied back to a person.</li><li>We do not share the data with third parties for advertising.</li><li>This applies to <strong>Sikshya Free and Sikshya Pro</strong> equally.</li></ul><h2 id="how-to-disable" tabindex="-1">How to disable <a class="header-anchor" href="#how-to-disable" aria-label="Permalink to &quot;How to disable&quot;">​</a></h2><ol class="step-list"><li>Open <span class="screen-path">Sikshya → Settings → Advanced</span>.</li><li>Find the <strong>Privacy &amp; Usage</strong> section.</li><li>Untick <strong>Share anonymous usage data with MantraBrain</strong>.</li><li>Click <strong>Save</strong>.</li></ol><p>Future sends are stopped immediately. The cron event is unscheduled on the next pageload.</p><h2 id="how-to-verify-what-was-sent" tabindex="-1">How to verify what was sent <a class="header-anchor" href="#how-to-verify-what-was-sent" aria-label="Permalink to &quot;How to verify what was sent&quot;">​</a></h2><p>If you want a paper trail of payloads:</p><ul><li>Enable WP-Cron logging via your favourite cron logger plugin.</li><li>Or run <code>wp cron event run sikshya_usage_send</code> via WP-CLI (verbose output) — Sikshya prints the JSON it would send.</li></ul><h2 id="questions" tabindex="-1">Questions? <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions?&quot;">​</a></h2><p>If you have questions or want a copy of the data we hold for your <code>instance_id</code>, reach out via the <a href="/plugins/sikshya/support">Support</a> page or open a ticket from <span class="screen-path">Sikshya → Help</span>.</p><p>Reference: this page mirrors the upstream privacy notice at <a href="https://docs.mantrabrain.com/sikshya-wordpress-plugin/which-types-of-data-are-being-tracked/" target="_blank" rel="noreferrer">docs.mantrabrain.com/sikshya-wordpress-plugin/which-types-of-data-are-being-tracked</a>.</p>',42)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
